493	/**
494	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
495	 * so tests can assert side-effects by reading that file — the second test-assertion channel
496	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
497	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
498	 *
499	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
500	 * SYNC) so a test reads the record immediately.
501	 */
502	@Service
503	public class Audit {
504	
505	    private final Path file;
506	
507	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
508	        this.file = Path.of(path);
509	    }
510	
511	    /** Append one audit record. Tests assert the exact line(s) in the file. */
512	    public synchronized void record(String entry) {
513	        try {
514	            Path parent = file.toAbsolutePath().getParent();
515	            if (parent != null) {
516	                Files.createDirectories(parent);
517	            }
518	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
519	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
520	        } catch (IOException e) {
521	            throw new UncheckedIOException(e);
522	        }
523	    }
524	
525	    /** Truncate the audit file (called by /__test__/reset for per-spec isolation). */
526	    public synchronized void clear() {
527	        try {
528	            Files.deleteIfExists(file);
529	        } catch (IOException e) {
530	            throw new UncheckedIOException(e);
531	        }
532	    }
